WITH event_rows AS (SELECT mktcode,tgtcode,bizdate,volume,MAX(volume) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS window_max FROM `newzl`.`hsj_stock_hq_basic`), event_keys AS (SELECT DISTINCT mktcode,tgtcode FROM event_rows WHERE bizdate='2026-04-14' AND volume>=window_max), indicator_keys AS (SELECT DISTINCT mktcode,tgtcode FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 3) AND volume>0) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN event_keys e ON e.mktcode=b.mktcode AND e.tgtcode=b.tgtcode JOIN indicator_keys i ON i.mktcode=b.mktcode AND i.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
